<script setup lang="ts">
/**
 * A read-only picture (`design/components/image.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/image.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onMounted, ref, useTemplateRef, watch } from 'vue'

import { Icon, devWarning } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/image.module.css'

export interface ImageProps {
  /**
   * The accessible name. An empty string declares the picture decorative and hides it from
   * assistive technology. Required, because only the caller knows which of the two a picture is.
   */
  alt: string
  /**
   * Width over height of a frame the picture sits in, for a source whose size is unknown or is
   * not the shape wanted. Alone, the frame is as wide as its container. With `width` and
   * `height`, it replaces their ratio.
   */
  aspectRatio?: number
  /**
   * The element's CORS mode. Absent, the request is made without CORS.
   */
  crossOrigin?: 'anonymous' | 'use-credentials'
  /**
   * How the picture sits in a frame whose ratio is not its own: `contain` shows all of it,
   * `cover` fills the frame and crops. Defaults to `contain`, because cropping removes content.
   */
  fit?: 'contain' | 'cover'
  /**
   * The picture's height in CSS pixels, given together with `width`.
   */
  height?: number
  /**
   * When the browser fetches the picture: `lazy` as the reader nears it, `eager` at once.
   * Defaults to `lazy`.
   */
  loading?: 'lazy' | 'eager'
  /**
   * The element's referrer policy. Absent, the page's own policy applies.
   */
  referrerPolicy?:
    | 'no-referrer'
    | 'no-referrer-when-downgrade'
    | 'origin'
    | 'origin-when-cross-origin'
    | 'same-origin'
    | 'strict-origin'
    | 'strict-origin-when-cross-origin'
    | 'unsafe-url'
  /**
   * The picture's URL. An empty string is the failed state: there is nothing to request.
   */
  src: string
  /**
   * The picture's width in CSS pixels, given together with `height`. The two reserve the box
   * before the picture loads and are its natural size; the frame is never wider than its
   * container.
   */
  width?: number
}

defineOptions({ name: 'Image', inheritAttrs: false })

const props = withDefaults(defineProps<ImageProps>(), { fit: 'contain', loading: 'lazy' })
const loaded = ref('')
const failed = ref('')
const image = useTemplateRef<HTMLElement>('image')
const status = computed(() =>
  props.src === '' || failed.value === props.src
    ? 'failed'
    : loaded.value === props.src
      ? 'loaded'
      : 'loading',
)
const ratio = computed(() =>
  props.aspectRatio !== undefined && props.aspectRatio > 0 && Number.isFinite(props.aspectRatio)
    ? props.aspectRatio
    : props.width !== undefined && props.height !== undefined && props.width > 0 && props.height > 0
      ? props.width / props.height
      : undefined,
)
const sized = computed(() => ratio.value !== undefined)
const decorative = computed(() => props.alt === '')
const settle = computed(() => () => {
  if (failed.value !== props.src) failed.value = ''
  const element = image.value as HTMLImageElement | null | undefined
  if (element == null || !element.complete) return
  if (element.naturalWidth > 0) loaded.value = props.src
  else element.src = props.src
})
const effect1 = () => {
  settle.value()
}
onMounted(effect1)
watch(() => props.src, effect1, { flush: 'post' })
const effect2 = () => {
  devWarning(
    (props.width === undefined) !== (props.height === undefined),
    'Image: `width` and `height` are given together. One alone gives no ratio and is ignored.',
  )
}
onMounted(effect2)
watch(() => (props.width === undefined) !== (props.height === undefined), effect2, {
  flush: 'post',
})
</script>

<template>
  <span
    :class="styles.frame"
    :style="{
      aspectRatio: ratio,
      inlineSize:
        width !== undefined && height !== undefined && width > 0 && height > 0
          ? `${width}px`
          : undefined,
    }"
    :data-state="status === 'loaded' ? undefined : status"
    :data-fit="fit"
    :data-sized="sized ? '' : undefined"
    data-member="image"
  >
    <!-- placeholder -->
    <span v-if="status === 'loading'" :class="styles.placeholder" aria-hidden="true" />
    <!-- fallback -->
    <span
      v-if="status === 'failed'"
      :class="styles.fallback"
      data-image-part="fallback"
      :role="!decorative ? 'img' : undefined"
      :aria-label="!decorative ? alt : undefined"
      :aria-hidden="decorative ? true : undefined"
    >
      <Icon name="error" />
    </span>
    <!-- image -->
    <img
      v-else
      ref="image"
      :class="styles.image"
      :loading="loading"
      :crossorigin="crossOrigin"
      :referrerpolicy="referrerPolicy"
      :src="src"
      :alt="alt"
      @load="loaded = src"
      @error="failed = src"
    />
  </span>
</template>
